WITH filtered_transactions AS (SELECT * FROM transactions WHERE amount BETWEEN 1700 AND 3800), amount_bucket_summary AS (SELECT CASE WHEN amount >= 4100 THEN 'high' WHEN amount >= 1600 THEN 'mid' ELSE 'low' END AS amount_bucket, MIN(amount) AS min_amount, SORT_ARRAY(COLLECT_SET(merchant)) AS merchant_list FROM filtered_transactions GROUP BY CASE WHEN amount >= 4100 THEN 'high' WHEN amount >= 1600 THEN 'mid' ELSE 'low' END) SELECT * FROM amount_bucket_summary WHERE min_amount >= 3100 ORDER BY min_amount
